insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('des-is-a-oids-deppal', 'Des is a oids Deppal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein altes Tepperl!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein alter Depp!\"  2. Das ist ein seniler Schwachkopf!  3. Das ist ein alter Trottel!"}]'::jsonb, ''),
  ('da-deppade-hod-wiida-moi-goa-nix-tscheckd', 'Da Deppade hod wiida moi goa nix tscheckd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Depperte hat wieder einmal gar nichts gecheckt!', '[{"kategorie": "wörtlich", "text": "\"Der Tepperte hat wieder einmal gar nichts gecheckt!\"  2. Der Hirnschüssler hat wieder mal gar nichts [[geschnallt]]!  3. Wieder mal hat der Trottel rein gar nichts begriffen!"}]'::jsonb, ''),
  ('a-deppada-min-nummansackl', 'a Deppada min Nummansackl', '', '', '', 'Echte Wiener Schmähperlen', 'ein Depperter mit Nummernsackel', '[{"kategorie": "wörtlich", "text": "\"ein Tepperter mit Nummerntüte\" (=ein Minderbemittelter, der seine Hausnummer [Wohnadresse] in einem umgehängten Sackerl mit sich trägt, weil er sonst nicht nach Hause finden würde\")"}, {"kategorie": "scherzhaft für", "text": "\"geistiger Blindgänger\", \"harmloser Depp\", Trottelchen, Hohlbirne, [[Depperl]], [[Dillo]], [[Dolm]], [[Hirnschüssler]]"}]'::jsonb, ''),
  ('des-is-a-deppada-min-nummansackal-dea-find-ned-amoi-haam', 'Des is a Deppada min Nummansackal - dea find ned amoi haam!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist ein Depperter mit Nummernsackerl - der findet nicht einmal heim!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Tepperter mit Nummerntüte - der findet nicht einmal heim!\"  2. Das ist ein geistiger Blindgänger mit Adressanhänger - anders findet der nicht heim!  3. Das ist ein Depp mit Nummernsackerl – und trotzdem verläuft er sich!"}]'::jsonb, 'a Deppada min Nummansackl'),
  ('dea-deppnschaeaedl-hods-hian-beim-scheissn-valuan', 'Dea Deppnschäädl hods Hian beim Scheissn valuan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Deppenschädel hat ''s Hirn beim Scheißen verloren!', '[{"kategorie": "wörtlich", "text": "\"Der Idiotenkopf hat ''s Hirn beim Kacken verloren!\"  2. Der Volltrottel hat sich sein letztes Hirnresterl beim Scheißen rausgepresst!  3. Diesem Vollpfosten ist der letzte Rest vom Hirn beim Kacken abgegangen!"}]'::jsonb, ''),
  ('i-brauch-a-doodlsichas-kochrezept-heechstns-drei-zuatoodn', 'I brauch a doodlsichas Kochrezept - heechstns drei Zuatoodn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich brauch ein dodelsicheres Kochrezept - höchstens drei Zutaten!', '[{"kategorie": "wörtlich", "text": "\"Ich brauche ein idiotensicheres Kochrezept - maximal drei Zutaten!\"  2. Gib mir ein Kochrezept, das narrensicher ist – drei Dinge rein, umrühren, fertig!  3. Ich suche was so einfaches, dass es sich quasi von selbst kocht!"}]'::jsonb, ''),
  ('i-brauch-a-deppnsichas-kochrezept-heechstns-drei-zuatoodn', 'I brauch a deppnsichas Kochrezept - heechstns drei Zuatoodn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich brauch ein deppensicheres Kochrezept - höchstens drei Zutaten!', '[{"kategorie": "wörtlich", "text": "\"Ich brauche ein idiotensicheres Kochrezept - maximal drei Zutaten!\"  2. Gib mir ein Kochrezept, das narrensicher ist – drei Dinge rein, umrühren, fertig!  3. Ich suche was so einfaches, dass es sich quasi von selbst kocht!"}]'::jsonb, ''),
  ('i-brauch-a-trottlsichas-kochrezept-heechstns-drei-zuatoodn', 'I brauch a trottlsichas Kochrezept - heechstns drei Zuatoodn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich brauch ein trottelsicheres Kochrezept - höchstens drei Zutaten!', '[{"kategorie": "wörtlich", "text": "\"Ich brauche ein idiotensicheres Kochrezept - maximal drei Zutaten!\"  2. Gib mir ein Kochrezept, das narrensicher ist – drei Dinge rein, umrühren, fertig!  3. Ich suche was so einfaches, dass es sich quasi von selbst kocht!"}]'::jsonb, ''),
  ('i-woa-so-deschparaad-i-haedad-fost-mei-ex-wiida-augruafn', 'I woa so deschparaad - I hädad fost mei Ex wiida augruafn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich war so desperat - ich hätte fast meine Ex wieder angerufen!', '[{"kategorie": "wörtlich", "text": "\"Ich war derart verzweifelt  - ich hätte fast meine Ex wieder angerufen!\"  2. Ich war derart [[im]] Arsch  - ich hätte fast meine Ex wieder angerufen!  3. Ich war so fertig, ich hätte fast meine Ex kontaktiert – und das sagt alles!"}]'::jsonb, ''),
  ('dea-dillo-hod-ned-amoi-an-schuiobschluss', 'Dea Dillo hod ned amoi an Schuiobschluss!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Dillo hat nicht einmal einen Schulabschluss!', '[{"kategorie": "wörtlich", "text": "\"Dieser Armleuchter hat nicht einmal einen Schulabschluss!\"  2. Dieser Schwachkopf hat nicht einmal die Schule beendet!  3. Diese Dumpfbacke hat die Schule nur von außen gesehen!"}]'::jsonb, ''),
  ('a-so-a-dillo', 'A so a Dillo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein so ein Dillo!', '[{"kategorie": "wörtlich", "text": "\"So ein Armleuchter!\"  2. Was für ein Vollpfosten!  3. Aber was für eine Dumpfbacke!"}]'::jsonb, ''),
  ('dea-hod-an-diiwae-auf-da-bian', 'Dea hod an Diiwä auf da Bian!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat einen Dippel auf dem Kopf', '[{"kategorie": "wörtlich", "text": "\"Der hat eine Beule am Kopf!\"  2. (scherzhaft für): Der hat einen [[Titscher]] an der Birne!  3. Der hat nicht alle Tassen im Schrank!"}]'::jsonb, ''),
  ('dea-hod-an-huasta-ausselossn-dass-de-fensta-gscheebad-haum', 'Dea hod an Huasta ausselossn, dass de Fensta gscheebad haum!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat einen Huster rausgelassen, dass die Fenster gescheppert haben!', '[{"kategorie": "wörtlich", "text": "\"Der hat so heftig gehustet, dass die Fenster gescheppert haben!\"  2. Sein Huster war so brachial, dass die Scheiben vibriert haben!  3. Der hat so kräftig gehustet, dass der Putz von der Wand gefallen ist!"}]'::jsonb, ''),
  ('weng-an-jedn-huasta-ind-luft-gee', 'weng an jedn Huasta ind Luft gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'wegen jedem Huster in die Luft gehen', '[{"kategorie": "wörtlich", "text": "\"wegen jeder Kleinigkeit in die Luft gehen\";  2.wegen jedem Schas an die Decke gehen"}, {"kategorie": "", "text": "wegen jedem Furz hochgehen wie eine Rakete"}]'::jsonb, ''),
  ('waunn-i-weng-an-jedn-huasta-ind-luft-gangad-warad-i-scho-im-oabit', 'Waunn I weng an jedn Huasta ind Luft gangad, warad I scho im Oabit!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich wegen jedem Huster i die Luft ginge, wäre ich schon im Orbit!', '[{"kategorie": "wörtlich", "text": "Wenn ich wegen jeder Kleinigkeit hochgehen würde wie eine Rakete, wäre ich längst im Orbit!   2. Wenn ich mich über jeden Blödsinn aufregen würd, müsste man mich per Satellit orten!  3. Wenn ich wegen jedem [[Schas]] an die Decke gehen würde, wäre ich längst nicht mehr unter euch!"}]'::jsonb, 'weng an jedn Huasta ind Luft gee'),
  ('de-sonografii-hod-eageebm-dassa-an-musklfaasariss-im-waadl-hod', 'De Sonografii hod eageebm, dassa an Musklfaasariss im Waadl hod!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Die Sonografie hat ergeben, dass er einen Muskelfaserriss im Wadl hat!', '[{"kategorie": "wörtlich", "text": "\"Laut Sonografie hat er einen Muskelfaserriss in der Wade!\"  2. \"Im Ultraschall wurde ein Muskelfaserriss der Wadenmuskulatur nachgewiesen!\"  3. \"Die sonografische Untersuchung bestätigte eine Faserruptur in der Wade!\""}]'::jsonb, ''),
  ('wem-de-waadln-viarerichtn', 'wem de Waadln viarerichtn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem die Waden nach vorne richten', '[{"kategorie": "wörtlich", "text": "\"jemandem die Beinschraube anlegen\" (historische Foltermethode, bei der dem Gefolterten mit einem Schraubstock Schien- und Wadenbein gebrochen wurden)"}, {"kategorie": "fig.", "text": "\"jemandem tüchtig auf den Pelz rücken\""}, {"kategorie": "", "text": "\"jemandem den Arsch aufreißen\""}]'::jsonb, 'I wea eich de Waadln viarerichtn, bis olle schbuads!'),
  ('i-wea-eich-de-waadln-viarerichtn-bis-olle-schbuads', 'I wea eich de Waadln viarerichtn, bis olle schbuads!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich werde euch die Waden nach vorne richten, bis ihr alle spurt!', '[{"kategorie": "wörtlich", "text": "\"Ich werde euch die Beinschrauben anlegen, bis ihr alle spurt!\"  2. Jetzt kriegt ihr von mir die Beinschraube, bis ihr alle gehorcht!  3. Ich zieh euch die Zügel so eng, bis ihr alle endlich funktioniert!"}]'::jsonb, 'wem de Waadln viarerichtn'),
  ('de-bian-bliad-friara-ois-da-opfae', 'De Bian bliad friara ois da Opfä!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Birne blüht früher als der Apfel!', '[{"kategorie": "wörtlich", "text": "\"Die Birne ist mit dem Blühen früher dran als der Apfel!\"  2. Die Birne beginnt ihre Blütezeit vor dem Apfelbaum!  3. Wenn die Birne schon im weißen Kleid steht, schläft der Apfelbaum noch!"}]'::jsonb, ''),
  ('heit-woama-bischkottalfoan-zwasitzakutschn-drei-leit-und-i-in-da-mittn', 'Heit woama Bischkottalfoan - Zwasitzakutschn, drei Leit und I in da Mittn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Heute waren wir Biskotterlfahren - Zweisitzerkutsche, drei Leute und ich in der Mitte!', '[{"kategorie": "wörtlich", "text": "\"Heute waren wir Biskotterlfahren - Zweisitzerkutsche, drei Leute und ich vornübergebeugt in der Mitte!\"   2. Heute waren wir Biskotterlfahren - Zweisitzerkutsche, drei Leute und ich wie ein Löffelbiskuit eingequetscht in der Mitte!  3. Ein Zweisitzer war’s, aber wir waren drei – logisch: Biskotterlfahrn!"}]'::jsonb, ''),
  ('mit-eich-zwa-daed-i-glott-bischkottalfoan', 'Mit eich zwa däd I glott Bischkottalfoan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mit euch zwei würd ich glatt Biskotterlfahren!', '[{"kategorie": "wörtlich", "text": "\"Mit euch zwei würd ich glatt einen flotten Dreier machen!\"  2. Mit euch beiden wär ich gern mal zu dritt unterwegs!  3. Wie wär''s, wenn ihr beiden und ich mal Sex zu dritt machen?"}]'::jsonb, ''),
  ('bitte-goa-schee', 'Bitte goa schee!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Bitte gar schön!', '[{"kategorie": "wörtlich", "text": "\"Also bitte!\"  2. Ach du meine Güte!  3. Nein, also wirklich! (Ausruf der Verwunderung bzw. Ablehnung)"}]'::jsonb, 'Bitte goa schee, muass des sei?'),
  ('bitte-goa-schee-muass-des-sei', 'Bitte goa schee, muass des sei?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bitte gar schön, muss das sein?', '[{"kategorie": "wörtlich", "text": "\"Also bitte, muss das wirklich sein?\"  2. Nein, also wirklich, brauch ma das jetzt?  3. Ach du meine Güte, muss das unbedingt sein?"}]'::jsonb, 'Bitte goa schee!'),
  ('dea-is-diiwaefloch-von-den-siichst-kan-groschn', 'Dea is diiwäfloch, von den siichst kan Groschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist dippelflach, von dem siehst du keinen Groschen!', '[{"kategorie": "wörtlich", "text": "\"Der ist völlig mittellos, von dem siehst du keinen Groschen!\"  2. Der ist blank bis auf die Knochen - von dem kriegst du keinen Cent!  3. Der ist chronisch pleite - von dem hast du nichts zu erwarten!"}]'::jsonb, ''),
  ('a-koatndippla-schbueued-ned-ums-gwinnan-sondan-waeura-ned-aufhean-kau', 'A Koatndippla schbüüd ned ums Gwinnan, sondan wäura ned aufhean kau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Kartentippler spielt nicht ums Gewinnen, sondern weil er nicht aufhören kann!', '[{"kategorie": "wörtlich", "text": "\"Ein Gewohnheitsspieler frönt dem Kartenspiel nicht um des Gewinnens willen, sondern weil er nicht aufhören kann!\"  2. Ein Kartentippler spielt nicht, weil er gewinnen will – sondern weil er’s nicht mehr lassen kann!  3. Der Kartentippler spielt nicht für den Sieg – sondern weil Aufhören keine Option mehr ist!"}]'::jsonb, ''),
  ('i-woid-liibe-owa-si-hod-in-diiwaewoong-gruafn', 'I woid Liibe, owa si hod in Diiwäwoong gruafn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich wollte Liebe, doch sie hat den Dippelwagen gerufen!', '[{"kategorie": "wörtlich", "text": "\"Ich wollte Liebe, doch sie hat die Funkstreife gerufen!\"  2. Ich wollte Gefühle, doch sie hat den Streifenwagen gerufen!  3. Ich hatte Schmetterlinge im Bauch – sie hatte 133 auf Kurzwahl!"}]'::jsonb, ''),
  ('de-dian-hods-hoa-gflochdn-troong-so-wias-bei-de-jungfraun-sitte-woa', 'De Dian hods Hoa gflochdn troong - so wias bei de Jungfraun Sitte woa!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Dirne hat das Haar geflochten getragen - so wie es bei den Jungfrauen Sitte war!', '[{"kategorie": "wörtlich", "text": "\"Die Dirne trug das Haar geflochten - so wie es bei den Jungfrauen Sitte war!\"  2. Die junge Maid trug das Haar in Zöpfen – so wie es sich bei züchtigen Jungfrauen geziemte!  3. Noch unverlobt, trug sie das Haar in Zöpfen – so wie’s der Brauch seit altersher von den Jungfern verlangt!"}]'::jsonb, ''),
  ('de-dian-woa-fiad-kuchl-zuaschdaendig-und-hod-fia-olle-im-heanhaus-des-essn-kochd', 'De Dian woa fiad Kuchl zuaschdändig und hod fia olle im Heanhaus des Essn kochd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Dirne war für die Küche zuständig und hat für alle im Herrenhaus das Essen gekocht!', '[{"kategorie": "wörtlich", "text": "\"Die Hausmagd war für die Küche zuständig und bereitete die Mahlzeiten für das gesamte Herrenhaus zu!\"  2. Als Küchenmagd versorgte sie die Herrschaft und das Gesinde im Herrenhaus mit Speis und Trank!  3. Die Dienstmagd war der Küche zugeteilt und kochte täglich für alle Bewohner des Herrenhauses!"}]'::jsonb, ''),
  ('de-dian-hod-in-mueuechkruag-auf-der-hueftn-troong-bloosshapad-iwan-taufeichdn-hof', 'De Dian hod in Müüchkruag auf der Hüftn troong, bloosshapad iwan taufeichdn Hof!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Dirne hat den Milchkrug auf der Hüfte getragen, barfuß über den taufeuchten Hof!', '[{"kategorie": "wörtlich", "text": "\"Die Dirne trug den Milchkrug auf der Hüfte, barfuß über den taufeuchten Hof!\"  2. Die Bauernmagd balancierte den Milchkrug auf der Hüfte, barfuß über den taufeuchten Hof!  3. Mit dem Milchkrug an der Hüfte ging die junge Landmagd barfuß über das taufrische Pflaster des Hofes!"}]'::jsonb, ''),
  ('in-da-klaan-gossn-schdengan-de-dianan-wia-aufgfaadld-unta-da-latean-de-lippn-rood-da-blick-vafiararisch', 'In da klaan Gossn schdengan de Dianan wia aufgfaadld unta da Latean - de Lippn rood, da Blick vafiararisch!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'In der kleinen Gasse stehen die Dirnen wie aufgefädelt unter der Laterne - die Lippen rot, der Blick verführerisch!', '[{"kategorie": "wörtlich", "text": "\"Unter dem flackernden Laternenlicht reihten sich die Dirnen wie an einer Schnur – rot geschminkte Lippen, lockender Blick!\"  2. In der schmalen Gasse standen die Prostituierten aufgereiht unter dem flackernden Laternenlicht, jede mit rotem Mund und einladendem Lächeln!  3. Wie bunte Hühner auf der Stange standen die Strichmädchen unter der Laterne – mit Kussmund und Katzenblick!"}]'::jsonb, 'wia aufgfaadld doschdee'),
  ('wia-aufgfaadld-doschdee', 'wia aufgfaadld doschdee', '', '', '', 'Wiener Sprüche, die sitzen!', 'wie aufgefädelt dastehen', '[{"kategorie": "wörtlich", "text": "\"wie aufgefädelt dastehen\""}, {"kategorie": "", "text": "wie aufgereiht dastehen"}, {"kategorie": "", "text": "in Reih und Glied stehen"}, {"kategorie": "", "text": "wie an der Schnur aufgereiht stehen"}]'::jsonb, ''),
  ('wea-mit-mia-dischkuriad-kriagd-de-baeun-gratis', 'Wea mit mia dischkuriad, kriagd de Bäun gratis!', '', '', '', 'Wiener Gaunersprache', 'Wer mit mir dischkuriert, kriegt die Beulen gratis!', '[{"kategorie": "wörtlich", "text": "\"Wer mit mir diskutiert, kriegt die Beulen gratis!\"  2. Er wollte diskutieren – jetzt zählt er seine Beulen!  3. Wer mit mir diskutiert, kriegt das Gegenargument gleich direkt ins Gesicht!"}]'::jsonb, ''),
  ('dea-doodl-kennt-si-in-da-doelefonzoeoen-varian-so-deppad-is-dea', 'Dea Doodl kennt si in da Dölefonzöön varian - so deppad is dea!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Dodel könnt sich in der Telefonzelle verirren – so deppert ist der!', '[{"kategorie": "wörtlich", "text": "\"Dieser Schwachkopf könnt sich in der Telefonzelle verirren – so belämmert ist der!\"  2. Der Trottel verirrt sich wahrscheinlich sogar beim Geradeausgehen!  3. Der könnte sich im Kreisverkehr verlaufen – so begnadet ist der!"}]'::jsonb, ''),
  ('a-doodl-mit-da-roodl', 'A Doodl mit da Roodl!', '', '', '', 'Echte Wiener Schmähperlen', 'ein Dodel mit der Rodel', '[{"kategorie": "wörtlich, Scherzreim", "text": "ein Idiot mit der [[Sackrodel]]! (Liedtext von Georg Danzer)"}, {"kategorie": "", "text": "Was für ein unbedarfter Idiot!  3. Ein Trottel vor dem Herrn!"}]'::jsonb, ''),
  ('de-doeoegln-si', 'De döögln si!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die dögeln sich', '[{"kategorie": "wörtlich", "text": "\"Die prügeln aufeinander ein!\"  2. Die hau’n sich die Köpfe ein!  3. (Deutschland): \"Die kloppen sich, was das Zeug hält!\""}]'::jsonb, ''),
  ('waunn-dea-no-a-deppads-wuat-sogd-doegl-i-eam-owe-vom-baangl', 'Waunn dea no a deppads Wuat sogd, dögl I eam owe vom Baangl!', '', '', '', 'Wiener Gaunersprache', 'Wenn der noch ein deppertes Wort sagt, dögle ich ihn runter vom Bankl!', '[{"kategorie": "wörtlich", "text": "\"Wenn der noch ein blödes Wort sagt, prügle ich ihn runter von der Sitzbank!\"  2. Noch ein Wort, und ich schlag ihn so flach, dass er unter der Bank liegt!  3. Noch einmal so eine blöde Meldung - und ich räum ich ihn eigenhändig von der Bank!"}]'::jsonb, ''),
  ('si-doeoegln', 'si döögln', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich dögeln', '[{"kategorie": "wörtlich", "text": "\"sich prügeln\" (lautmalerisches Wort, das den dumpfen Klang von Schlägen nachahmt [„dög–dög–dög“])"}, {"kategorie": "allg.", "text": "sich schlagen, sich prügeln, [[si pöözn]]"}]'::jsonb, 'De döögln si!'),
  ('de-zwaa-haum-si-doeoegld-wia-de-viacha', 'De zwaa haum si döögld wia de Viacha!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die zwei haben sich gedögelt wie die Viecher!', '[{"kategorie": "wörtlich", "text": "Die beiden haben sich geprügelt wie wilde Tiere!“  2. Die haben aufeinander eingedroschen, dass die Fetzen geflogen sind!  3. Die sind aufeinander losgegangen wie zwei tollwütige Hunde!"}]'::jsonb, 'si döögln'),
  ('moch-aufd-schdiifae-an-doppla-drauf-daunn-sans-wiida-wia-neich', 'Moch aufd Schdiifä an Doppla drauf, daunn sans wiida wia neich!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Mach auf die Stiefel ''nen Doppler drauf, dann sind sie wieder wie neu!', '[{"kategorie": "wörtlich", "text": "\"Mach auf die Stiefel neue Sohlen drauf, dann sind sie wieder wie neu!\"  2. Neue Sohlen drauf, und die Stiefel sind wie generalüberholt!  3. Lass die Stiefel neu besohlen, dann sind sie wieder einsatzbereit!"}]'::jsonb, ''),
  ('mid-an-genialn-doppla-haums-de-gaunze-obwea-ausgheebaed', 'Mid an genialn Doppla haums de gaunze Obwea ausgheebäd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Mit einem genialen Doppler haben sie die ganze Abwehr ausgehebelt!', '[{"kategorie": "wörtlich", "text": "\"Mit einem genialen Doppelpass haben sie die ganze Abwehr ausgehebelt!\"  2. Mit einem perfekt getimten Doppelpass haben sie die gesamte Abwehr ausgespielt!  3. Mit einem traumhaften Doppelpass spielten sie die Abwehr aus wie Amateure!"}]'::jsonb, ''),
  ('dem-doim-kaunnst-a-lateanan-umhaengan-daunn-hod-deppadsei-wenigstns-a-liachd', 'Dem Doim kaunnst a Lateanan umhängan - daunn hod Deppadsei wenigstns a Liachd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dem Dolm kannst du eine Laterne umhängen – dann hat Deppertsein wenigstens ein Licht!', '[{"kategorie": "wörtlich", "text": "\"Diesem Schwachkopf kannst du eine Laterne umhängen – dann hat Blödsein wenigstens ein Licht!\"  2. Dem kannst a Glühbirn auf’s Hirn picken – dann siehst wenigstens, wo die gesitige Verwirrung herkommt!  3. Wenn Blödheit scheinen tät, wär der Hirnschüssler a Straßenbeleuchtung!"}]'::jsonb, ''),
